.mx_AccessibleButton {
    cursor: pointer;

    &.mx_AccessibleButton_disabled {
        cursor: default;

        &.mx_AccessibleButton_kind_primary,
        &.mx_AccessibleButton_kind_primary_outline,
        &.mx_AccessibleButton_kind_primary_sm,
        &.mx_AccessibleButton_kind_link,
        &.mx_AccessibleButton_kind_link_inline,
        &.mx_AccessibleButton_kind_link_sm {
            opacity: 0.4;
        }
    }

    &.mx_AccessibleButton_hasKind {
        padding: 7px 18px;
        text-align: center;
        border-radius: 8px;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        font-size: $font-14px;
        border: none; // override default <button /> styles
        word-break: keep-all; // prevent button text in Chinese/Japanese/Korean (CJK) from being collapsed

        &.mx_AccessibleButton_kind_primary_sm,
        &.mx_AccessibleButton_kind_danger_sm,
        &.mx_AccessibleButton_kind_link_sm {
            padding: 5px 12px;
        }

        &.mx_AccessibleButton_kind_primary_sm {
            color: $button-primary-fg-color;
            background-color: $accent;
        }

        &.mx_AccessibleButton_kind_danger_sm {
            color: $button-danger-fg-color;
            background-color: $alert;
        }

        &.mx_AccessibleButton_kind_link_sm {
            color: $accent;
        }

        &.mx_AccessibleButton_kind_confirm_sm {
            background-color: $accent;

            &::before {
                mask-image: url('$(res)/img/feather-customised/check.svg');
            }
        }

        &.mx_AccessibleButton_kind_cancel_sm {
            background-color: $alert;

            &::before {
                mask-image: url('$(res)/img/feather-customised/x.svg');
            }
        }
    }

    &.mx_AccessibleButton_kind_primary,
    &.mx_AccessibleButton_kind_primary_outline,
    &.mx_AccessibleButton_kind_secondary {
        font-weight: 600;
    }

    &.mx_AccessibleButton_kind_primary,
    &.mx_AccessibleButton_kind_primary_outline {
        border: 1px solid $accent;
    }

    &.mx_AccessibleButton_kind_primary {
        color: $button-primary-fg-color;
        background-color: $accent;
    }

    &.mx_AccessibleButton_kind_primary_outline {
        color: $accent;
        background-color: $button-secondary-bg-color;
    }

    &.mx_AccessibleButton_kind_secondary {
        color: $accent;
    }

    &.mx_AccessibleButton_kind_danger {
        color: $button-danger-fg-color;
        background-color: $alert;

        &.mx_AccessibleButton_disabled {
            color: $button-danger-disabled-fg-color;
            background-color: $button-danger-disabled-bg-color;
        }
    }

    &.mx_AccessibleButton_kind_danger_outline {
        color: $alert;
        background-color: transparent;
        border: 1px solid $alert;

        &.mx_AccessibleButton_disabled {
            color: $button-danger-disabled-bg-color;
            border-color: $button-danger-disabled-bg-color;
        }
    }

    &.mx_AccessibleButton_kind_danger_sm {
        &.mx_AccessibleButton_disabled {
            color: $button-danger-disabled-fg-color;
            background-color: $button-danger-disabled-bg-color;
        }
    }

    &.mx_AccessibleButton_kind_link,
    &.mx_AccessibleButton_kind_link_inline {
        color: $accent;
        font-size: inherit;
        font-weight: normal;
        line-height: inherit;
    }

    &.mx_AccessibleButton_kind_link {
        padding: 0;
    }

    &.mx_AccessibleButton_kind_link_inline {
        display: inline;
        padding: 0 2px;
    }

    &.mx_AccessibleButton_kind_confirm_sm,
    &.mx_AccessibleButton_kind_cancel_sm {
        padding: 0px;
        width: 16px;
        height: 16px;
        border-radius: 100%;
        position: relative;
        display: block;

        &::before {
            content: "";
            display: block;
            position: absolute;
            top: 0;
            bottom: 0;
            left: 0;
            right: 0;
            background-color: #ffffff;
            mask-repeat: no-repeat;
            mask-position: center;
            mask-size: 80%;
        }
    }
}

    max-width: 100%;
    max-height: 100%;
    pointer-events: none;
    padding: 0;
}

.mx_Dialog_header {
    position: relative;
    padding: 3px 0;
    margin-bottom: 10px;
}

.mx_Dialog_titleImage {
    vertical-align: sub;
    width: 25px;
    height: 25px;
    margin-left: -2px;
    margin-right: 4px;
    margin-bottom: 2px;
}

.mx_Dialog_title {
    color: $dialog-title-fg-color;
    display: inline-block;
    width: 100%;
    box-sizing: border-box;
}

.mx_Dialog_header.mx_Dialog_headerWithButton > .mx_Dialog_title {
    text-align: center;
}
.mx_Dialog_header.mx_Dialog_headerWithCancel {
    padding-right: 20px; // leave space for the 'X' cancel button
}

.mx_Dialog_title.danger {
    color: $alert;
